import { EntityService, type IEntitiesService } from '@kinotic/structures-api'
import { Todo } from '../../model/Todo.js'


/**
 * Base Service for interacting with Todo entities
 * This class was generated by the Structures CLI. And will be overwritten if the CLI is run again.
 */
export class BaseTodoEntityService extends EntityService<Todo> {

  private readonly shouldValidate: boolean

  constructor(shouldValidate: boolean = true, entitiesService?: IEntitiesService) {
    super('bun-test', 'Todo', entitiesService)
    this.shouldValidate = shouldValidate
  }

  protected async beforeSaveOrUpdate(entity: Todo): Promise<Todo> {
    if (this.shouldValidate) {
      return this.validate(entity)
    } else {
      return entity
    }
  }

  protected async beforeBulkSaveOrUpdate(entities: Todo[]): Promise<Todo[]> {
    if (this.shouldValidate) {
      const validatedEntities: Todo[] = []
      for (let entity of entities) {
        validatedEntities.push(this.validate(entity))
      }
      return validatedEntities
    } else {
      return entities
    }
  }

  validate(entity: Todo): Todo {
    let ret: any
    if (entity) {
      ret = (ret ? ret : {})
      ret.id = entity.id
      ret.title = entity.title
      ret.description = entity.description
      ret.completed = entity.completed
    }

    return ret
  }

}
